H.background();
const h = P.h, d = P.d;
// Window must contain the solutions x = h ± d so both markers stay visible.
const xspan = Math.max(8, Math.abs(h) + Math.max(0, d) + 1.5);
const ymax = Math.max(10, d + 2);
const v = H.plot2d({ xMin: -xspan, xMax: xspan, yMin: -2, yMax: ymax });
v.grid(); v.axes();
const f = x => Math.abs(x - h);
v.fn(f, { color: H.colors.accent, width: 3 });
v.line(-xspan, d, xspan, d, { color: H.colors.accent2, width: 2.5 });
v.dot(h, 0, { r: 5, fill: H.colors.warn });
if (d >= 0) {
  const s1 = h + d, s2 = h - d;
  v.dot(s1, d, { r: 7, fill: H.colors.good });
  v.dot(s2, d, { r: 7, fill: H.colors.good });
  v.line(s1, 0, s1, d, { color: H.colors.violet, width: 1.2, dash: [3, 3] });
  v.line(s2, 0, s2, d, { color: H.colors.violet, width: 1.2, dash: [3, 3] });
}
const pulse = 0.5 + 0.5 * Math.sin(t * 2.5);
const xs = h + Math.max(0, d) * Math.sin(t * 0.8);
v.dot(xs, f(xs), { r: 4 + 2 * pulse, fill: H.colors.warn });
H.text("Solve  |x − h| = d", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const sol = d > 1e-9 ? "x = " + (h + d).toFixed(2) + "  or  x = " + (h - d).toFixed(2) : d < -1e-9 ? "no solution (d < 0)" : "x = " + h.toFixed(2) + " (one solution)";
H.text(sol + "   →  x − h = ±d", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "|x−h|", color: H.colors.accent }, { label: "y = d", color: H.colors.accent2 }, { label: "solutions", color: H.colors.good }], H.W - 160, 28);
